func check_wave_completion() -> void:
    if current_enemy_count > 0: return

    var all_spawners_cleared = true
    var other_spawners = get_tree().get_nodes_in_group("spawners")

    for spawner in other_spawners:
        if is_instance_valid(spawner) and spawner.current_enemy_count > 0:
            all_spawners_cleared = false
            break

    if all_spawners_cleared:
        for spawner in other_spawners:
            if spawner.has_method("end_wave"):
                spawner.end_wave()

private Vector3 GetRandomPointOnNavMesh(Vector3 center, float radius)
{
    Vector3 randomDirection = Random.insideUnitSphere * radius;
    randomDirection += center;
    if (NavMesh.SamplePosition(randomDirection, out NavMeshHit hit, radius, NavMesh.AllAreas))
        return hit.position;
    return center;
}

protected override void DoAttacking()
{
    float distanceToPlayer = Vector3.Distance(transform.position, playerObj.transform.position);
    if (distanceToPlayer <= explosionRange)
    {
        Instantiate(explosionEffectPrefab, transform.position, Quaternion.identity);
        playerManager.PlayerHealthProperty -= explosionDamage;
        Destroy(gameObject);
    }
    else
    {
        agent.SetDestination(playerObj.transform.position);
    }
}

