public float PlayerHealthProperty
{
    set
    {
        float damageTaken = PlayerHealth - Mathf.Clamp(value, 0, MaxHealth);
        PlayerHealth = Mathf.Clamp(value, 0, MaxHealth);

        if (damageTaken > 0)
            ShowBloodOverlay(damageTaken);

        if (PlayerHealth <= 0f)
        {
            PlayerLife--;
            if (PlayerLife <= 0) PlayerDeathUI();
            else Respawn();
        }
    }
}

void ShowBloodOverlay(float damageAmount)
{
    bloodAlpha += damageAmount / MaxHealth;
    bloodAlpha = Mathf.Clamp01(bloodAlpha);
}

